function MarketChart({asset,price,base,period,setPeriod,money}){const counts={'1D':24,'1W':7,'1M':30,'1Y':52},count=counts[period]||30,seed=[...asset.id].reduce((sum,char)=>sum+char.charCodeAt(0),0),values=Array.from({length:count},(_,index)=>{const progress=index/Math.max(1,count-1),wave=Math.sin((index+seed)*1.73)*.018+Math.sin((index+seed)*.43)*.025+Math.sin((index+seed)*.16)*.028,drift=(.5-progress)*.018;return price*(1+wave*(1-progress)+drift)});values[values.length-1]=price;const low=Math.min(...values),high=Math.max(...values),pad=Math.max((high-low)*.16,price*.004),min=low-pad,max=high+pad,points=values.map((value,index)=>({x:68+index*(632/Math.max(1,values.length-1)),y:20+(max-value)/(max-min)*156})),path=points.map((point,index)=>`${index?'L':'M'}${point.x.toFixed(1)},${point.y.toFixed(1)}`).join(' '),area=`${path} L700,184 L68,184 Z`,fillId=`market-fill-${asset.id}-${period}`,change=(price/base-1)*100,rising=price>=base;return <Card className="market-chart-card" title={<span className="chart-title"><TrendingUp size={16}/> {asset.name}</span>} extra={<div className="chart-ranges" role="group" aria-label="Chart time range">{Object.keys(counts).map(range=><button key={range} className={period===range?'active':''} aria-pressed={period===range} onClick={()=>setPeriod(range)}>{range}</button>)}</div>}><div className="chart-quote-head"><div><span>SIMULATED PRICE</span><strong>{money(price)}</strong></div><span className={`chart-change ${rising?'up':'down'}`}>{rising?'+':''}{change.toFixed(2)}% <small>vs reference</small></span></div><div className="market-chart-wrap"><svg viewBox="0 0 720 218" preserveAspectRatio="none" role="img" aria-label={`${asset.name} illustrative ${period} price chart`}><defs><linearGradient id={fillId} x1="0" x2="0" y1="0" y2="1"><stop offset="0%" stopColor={rising?'#2b9a73':'#dc6464'} stopOpacity=".22"/><stop offset="100%" stopColor={rising?'#2b9a73':'#dc6464'} stopOpacity="0"/></linearGradient></defs>{[28,67,106,145,184].map(y=><line key={y} x1="68" x2="700" y1={y} y2={y} className="chart-gridline"/>)}<text x="3" y="31">{money(max)}</text><text x="3" y="109">{money((max+min)/2)}</text><text x="3" y="187">{money(min)}</text><path d={area} fill={`url(#${fillId})`}/><path d={path} fill="none" stroke={rising?'#208962':'#d64d4d'} strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round" vectorEffect="non-scaling-stroke"/><circle cx={points.at(-1).x} cy={points.at(-1).y} r="4" fill={rising?'#208962':'#d64d4d'} stroke="#fff" strokeWidth="2" vectorEffect="non-scaling-stroke"/></svg></div><div className="chart-axis"><span>{period==='1D'?'09:00':period==='1W'?'Mon':period==='1M'?'1': 'Jan'}</span><span>{period==='1D'?'13:00':period==='1W'?'Wed':period==='1M'?'15':'Apr'}</span><span>{period==='1D'?'15:30':period==='1W'?'Fri':period==='1M'?'30':'Jul'}</span><span>Now</span></div><p className="chart-disclaimer"><Info size={13}/> Illustrative practice data. This is not a live market feed.</p></Card>}
function MarketWorkspace({data,assets,prices,asset,setAsset,qty,setQty,search,setSearch,money,totalAssets,portfolioPnl,trade,chartPeriod,setChartPeriod,orderType,setOrderType,limitPrice,setLimitPrice,placeLimitOrder,marketScope,setMarketScope,watchlist,setWatchlist,priceAlerts,setPriceAlerts,alertValue,setAlertValue,alertMode,setAlertMode,marketTick,notify}){const selected=assets.find(item=>item.id===asset)||assets[0],price=prices[selected.id]||selected.base,change=(price/selected.base-1)*100;let visible=assets.filter(item=>`${item.name} ${item.kind}`.toLowerCase().includes(search.toLowerCase()));if(marketScope==='watchlist')visible=visible.filter(item=>watchlist.includes(item.id));if(marketScope==='movers')visible=visible.sort((a,b)=>Math.abs((prices[b.id]/b.base-1)*100)-Math.abs((prices[a.id]/a.base-1)*100));const toggleWatch=id=>setWatchlist(current=>current.includes(id)?current.filter(item=>item!==id):[...current,id]);const createAlert=()=>{const target=Number(alertValue);if(target<=0){notify('Enter a price above zero for the alert.');return}setPriceAlerts(current=>[...current,{id:Date.now(),asset:selected.id,target,direction:alertMode}]);notify(`Price alert set for ${selected.name}.`);setAlertValue('')};return <div className="market-page"><div className="market-summary-strip"><div><span>Practice wallet</span><b>{money(data.wallet)}</b></div><div><span>Portfolio market value</span><b>{money(totalAssets)}</b></div><div className={`market-pnl ${portfolioPnl>=0?'positive':'negative'}`}><span>Total practice P/L</span><b>{portfolioPnl>=0?'+':''}{money(portfolioPnl)}</b></div><div className="market-mode"><span className="market-live-dot"/> SIM LIVE <small>Updated {new Date(marketTick).toLocaleTimeString([],{hour:'2-digit',minute:'2-digit',second:'2-digit'})}</small></div></div><div className="market-workspace"><Card className="market-watch-card" title="Watchlist" extra={<span className="soft-tag">{watchlist.length} pinned</span>}><label className="market-search"><span>⌕</span><input aria-label="Search market assets" value={search} onChange={event=>setSearch(event.target.value)} placeholder="Search an asset"/></label><div className="market-watch-filters"><button className={marketScope==='watchlist'?'active':''} onClick={()=>setMarketScope('watchlist')}>Pinned</button><button className={marketScope==='all'?'active':''} onClick={()=>setMarketScope('all')}>All assets</button><button className={marketScope==='movers'?'active':''} onClick={()=>setMarketScope('movers')}>Top movers</button></div><div className="market-list">{visible.map(item=>{const current=prices[item.id]||item.base,delta=(current/item.base-1)*100,pinned=watchlist.includes(item.id);return <div className={`market-row-wrap ${asset===item.id?'selected':''}`} key={item.id}><button className={`market-row ${asset===item.id?'active':''}`} onClick={()=>setAsset(item.id)}><span className="market-symbol">{item.name.slice(0,2).toUpperCase()}</span><span><b>{item.name}</b><small>{item.kind}</small></span><strong>{money(current)}<small className={delta>=0?'market-change':'market-loss'}>{delta>=0?'+':''}{delta.toFixed(2)}%</small></strong></button><button type="button" className={`watch-star ${pinned?'pinned':''}`} aria-label={pinned?'Remove from pinned watchlist':'Pin to watchlist'} title={pinned?'Unpin asset':'Pin asset'} onClick={event=>{event.stopPropagation();toggleWatch(item.id)}}>{pinned?'★':'☆'}</button></div>})}{!visible.length&&<div className="market-empty">{marketScope==='watchlist'?'No pinned assets match. Choose All assets to add some.':'No assets match that search.'}</div>}</div></Card><div className="market-main"><MarketChart asset={selected} price={price} base={selected.base} period={chartPeriod} setPeriod={setChartPeriod} money={money}/><Card className="order-card" title={`Practice order · ${selected.name}`} extra={<span className="soft-tag green-tag">Virtual</span>}><div className="order-type-toggle" role="group" aria-label="Practice order type">{[['market','Market'],['limit','Limit']].map(([id,label])=><button key={id} className={orderType===id?'active':''} aria-pressed={orderType===id} onClick={()=>setOrderType(id)}>{label}</button>)}</div><div className="order-quote"><span><small>SIMULATED PRICE</small><b>{money(price)}</b></span><span className={change>=0?'market-change':'market-loss'}>{change>=0?'+':''}{change.toFixed(2)}%</span></div><label className="field-label">Units<input type="number" min="1" step="1" value={qty} onChange={event=>setQty(event.target.value)}/></label>{orderType==='limit'&&<label className="field-label">Limit price<input type="number" min="0.01" step="0.01" value={limitPrice} onChange={event=>setLimitPrice(event.target.value)} placeholder={money(price)}/><small>Buy fills at or below your limit; sell fills at or above it.</small></label>}<div className="trade-total"><span>Estimated order value</span><b>{money((Number(qty)||0)*(orderType==='limit'&&Number(limitPrice)>0?Number(limitPrice):price))}</b></div><div className="trade-buttons"><Button onClick={()=>orderType==='market'?trade('buy'):placeLimitOrder('buy')}>{orderType==='market'?'Buy virtually':'Place buy limit'}</Button><Button kind="secondary" onClick={()=>orderType==='market'?trade('sell'):placeLimitOrder('sell')}>{orderType==='market'?'Sell units':'Place sell limit'}</Button></div><p className="hint">{orderType==='market'?'Market practice order uses the current simulated quote.':'Limit orders wait for a simulated quote to reach your price.'} No real trades or live prices.</p></Card><Card className="price-alert-card" title="Price alerts" extra={<span className="soft-tag">{priceAlerts.length} active</span>}><div className="price-alert-form"><select aria-label="Alert direction" value={alertMode} onChange={event=>setAlertMode(event.target.value)}><option value="above">Rises above</option><option value="below">Falls below</option></select><input aria-label="Alert price" type="number" min="0.01" step="0.01" placeholder={money(price)} value={alertValue} onChange={event=>setAlertValue(event.target.value)}/><Button onClick={createAlert}>Set alert</Button></div>{priceAlerts.length?<div className="price-alert-list">{priceAlerts.map(alert=>{const item=assets.find(entry=>entry.id===alert.asset);return <div className="price-alert-row" key={alert.id}><span><b>{item?.name||alert.asset}</b><small>{alert.direction==='above'?'Rises above':'Falls below'} {money(alert.target)}</small></span><button onClick={()=>setPriceAlerts(current=>current.filter(entry=>entry.id!==alert.id))} aria-label="Remove price alert">×</button></div>})}</div>:<p className="hint">Get a notice when a simulated quote crosses your level.</p>}</Card></div></div><Card title="Your practice portfolio" className="portfolio-card" extra={<span className="soft-tag">{data.portfolio.length} holdings</span>}>{data.portfolio.length?<div className="activity-list">{data.portfolio.map(position=>{const item=assets.find(entry=>entry.id===position.id),current=prices[position.id]||0,value=current*position.qty,pnl=(current-(Number(position.avgPrice)||0))*position.qty;return <div key={position.id} className="activity-row"><span className="market-symbol">{item?.name.slice(0,2).toUpperCase()}</span><span><b>{item?.name||position.id}</b><small>{position.qty} units · Avg. {money(position.avgPrice)}</small></span><span className="holding-value"><b>{money(value)}</b><small className={pnl>=0?'positive':'negative'}>{pnl>=0?'+':''}{money(pnl)}</small></span></div>})}</div>:<div className="empty-state"><span>◷</span><b>Your portfolio is ready</b><p>Place a virtual order to see holdings and compare them with your practice wallet.</p></div>}</Card></div>}function MtfPractice({data,update,trackActivity,notify,money}){const wallet=Math.max(0,Number(data.wallet)||0),[margin,setMargin]=useState(String(Math.min(1000,wallet))),[leverage,setLeverage]=useState(2),[days,setDays]=useState(7),[move,setMove]=useState(5);const own=Math.min(wallet,Math.max(0,Number(margin)||0)),exposure=own*leverage,borrowed=exposure-own,interest=borrowed*.12*Math.max(1,Number(days)||1)/365,gross=exposure*(Number(move)||0)/100,net=gross-interest,returnPct=own?net/own*100:0,remaining=own+net,risk=remaining<=0?'High risk':remaining<own*.3?'Very high risk':net<0?'Loss scenario':'Illustrative scenario';const saveRun=()=>{if(own<=0){notify('Enter a margin amount within your practice wallet.');return}update(state=>({...state,mtfSimulations:(state.mtfSimulations||0)+1}));trackActivity('MTF practice scenario',`${leverage}× exposure · ${move>=0?'+':''}${move}% price move`);notify('Practice scenario saved. No virtual funds were moved.');};return <div className="mtf-page"><div className="mtf-intro"><span className="mtf-badge">MTF · PAPER PRACTICE</span><h2>Understand margin before you use it</h2><p>Explore how borrowed buying power can magnify both gains and losses. Nothing here connects to a broker or uses real money.</p></div><div className="mtf-layout"><Card title="Build a practice scenario" extra={<span className="soft-tag">Hypothetical</span>}><label className="field-label">Your margin amount <small>Practice wallet: {money(wallet)}</small><input type="number" min="0" max={wallet} value={margin} onChange={event=>setMargin(event.target.value)} placeholder="Enter an amount"/></label><div className="mtf-control"><span>Buying power multiple</span><div className="mtf-leverage">{[2,3,4].map(value=><button key={value} className={leverage===value?'active':''} onClick={()=>setLeverage(value)}>{value}×</button>)}</div></div><label className="field-label">Holding period<input type="number" min="1" max="365" value={days} onChange={event=>setDays(event.target.value)}/></label><div className="mtf-control"><div className="mtf-control-label"><span>Illustrative price move</span><b className={move<0?'negative':''}>{move>0?'+':''}{move}%</b></div><div className="mtf-moves">{[-10,-5,0,5,10].map(value=><button key={value} className={move===value?'active':''} onClick={()=>setMove(value)}>{value>0?'+':''}{value}%</button>)}</div></div><div className="mtf-disclosure"><Info size={15}/><span>Interest is estimated at 12% per year for learning only. Actual MTF rates, charges, collateral rules and liquidation policies vary by broker and can change.</span></div><Button onClick={saveRun} disabled={own<=0}>Save practice scenario</Button></Card><div className="mtf-results"><Card title="Position breakdown" extra={<span className="soft-tag">{leverage}× exposure</span>}><div className="mtf-summary"><div><span>Your margin</span><b>{money(own)}</b></div><div><span>Simulated borrowing</span><b>{money(borrowed)}</b></div><div><span>Total position</span><b>{money(exposure)}</b></div><div><span>Estimated interest</span><b>{money(interest)}</b></div></div><div className={`mtf-outcome ${net<0?'negative':''}`}><span>Estimated net result</span><strong>{net>0?'+':''}{money(net)}</strong><small>{returnPct>0?'+':''}{returnPct.toFixed(1)}% on your margin · {risk}</small></div>{remaining<own*.3&&own>0&&<div className="mtf-risk"><CircleAlert size={16}/><span>A sharp price drop could put most or all of your margin at risk. Borrowing magnifies losses too.</span></div>}</Card><Card title="What if the price moves?" extra={<span className="soft-tag">Scenario table</span>}><div className="mtf-scenarios"><div className="mtf-scenario-head"><span>Price change</span><span>Net result after estimated interest</span></div>{[-10,-5,0,5,10].map(value=>{const result=exposure*value/100-interest;return <div className="mtf-scenario" key={value}><b className={value>0?'positive':value<0?'negative':''}>{value>0?'+':''}{value}%</b><span className={result>0?'positive':result<0?'negative':''}>{result>0?'+':''}{money(result)}</span></div>})}</div><p className="hint">A simplified learning model. It does not include taxes, broker fees, margin calls or changing rates.</p></Card></div></div></div>}
const practiceFundCatalog=[{id:'index',name:'India 50 Index Practice Fund',category:'Index',nav:142.8,risk:'High',fee:'0.20%',about:'Tracks a broad large-company index in this educational simulation.'},{id:'balanced',name:'Balanced Growth Practice Fund',category:'Hybrid',nav:58.4,risk:'Moderate',fee:'0.45%',about:'A practice mix of shares and bonds to explore diversification.'},{id:'debt',name:'Steady Debt Practice Fund',category:'Debt',nav:28.12,risk:'Lower, not risk-free',fee:'0.30%',about:'A fixed-income learning example. Returns and principal are not guaranteed.'}];
function addFundUnits(state,fund,amount,kind){const units=amount/fund.nav,old=(state.fundHoldings||[]).find(position=>position.fundId===fund.id),holding=old?{...old,units:old.units+units,invested:old.invested+amount}:{fundId:fund.id,units,invested:amount};return {...state,wallet:(Number(state.wallet)||0)-amount,fundHoldings:old?state.fundHoldings.map(position=>position.fundId===fund.id?holding:position):[...(state.fundHoldings||[]),holding],fundTransactions:[{id:`fund-${Date.now()}-${Math.random()}`,fundId:fund.id,kind,amount,units,nav:fund.nav,date:date()},...(state.fundTransactions||[])]}}
function OrdersView({orders,assets,money,filter,setFilter,cancelOrder}){const filters=[['all','All orders'],['pending','Pending'],['filled','Executed'],['cancelled','Cancelled'],['rejected','Rejected']];const shown=[...orders].filter(order=>filter==='all'||order.status===filter).sort((a,b)=>(Number(b.createdAt)||0)-(Number(a.createdAt)||0));const counts=Object.fromEntries(filters.map(([id])=>[id,id==='all'?orders.length:orders.filter(order=>order.status===id).length]));return <div className="orders-page"><div className="orders-heading"><div><span className="mtf-badge">PRACTICE TRADING</span><h2>Orders</h2><p>Review your virtual trades and manage orders waiting for a simulated price.</p></div><span className="orders-safe-tag"><span/> Paper trading</span></div><div className="orders-summary"><div><span>Open orders</span><b>{counts.pending}</b><small>Waiting for your limit</small></div><div><span>Executed</span><b>{counts.filled}</b><small>Completed practice trades</small></div><div><span>All orders</span><b>{orders.length}</b><small>Across every status</small></div></div><Card className="orders-card" title="Order book" extra={<span className="soft-tag">{shown.length} shown</span>}><p className="muted">Market orders use the current simulated quote. Limit orders remain open until the quote reaches your price or you cancel them.</p><div className="order-filters" role="tablist" aria-label="Filter orders">{filters.map(([id,label])=><button role="tab" aria-selected={filter===id} key={id} className={filter===id?'active':''} onClick={()=>setFilter(id)}>{label}<span>{counts[id]}</span></button>)}</div>{shown.length?<div className="orders-list">{shown.map(order=>{const item=assets.find(asset=>asset.id===order.asset),kind=order.kind||(order.limitPrice?'limit':'market'),statusLabel={filled:'Executed',pending:'Open',cancelled:'Cancelled',rejected:'Rejected'}[order.status]||order.status,price=order.fillPrice??order.limitPrice;return <article className="order-row" key={order.id}><span className={`order-side ${order.type==='buy'?'buy':'sell'}`}>{order.type.toUpperCase()}</span><span className="order-instrument"><b>{item?.name||order.asset}</b><small>{order.qty} {order.qty===1?'unit':'units'} <i>·</i> {kind.toUpperCase()}</small><small className="order-time">{new Date(order.createdAt||Date.now()).toLocaleString([],{month:'short',day:'numeric',hour:'2-digit',minute:'2-digit'})}</small></span><span className="order-price-block"><small>{order.status==='filled'?'Average price':kind==='limit'?'Limit price':'Order type'}</small><b>{price!=null?money(price):'Market'}</b></span><span className="order-total-block"><small>{order.status==='filled'?'Executed value':'Est. value'}</small><b>{money((Number(price)||Number(order.fillPrice)||0)*Number(order.qty||0))}</b></span><span className={`order-status ${order.status}`}><i/>{statusLabel}</span>{order.status==='pending'?<button className="order-cancel" onClick={()=>cancelOrder(order.id)}>Cancel</button>:<span className="order-result">{order.status==='filled'?'✓':order.status==='rejected'?'!':'—'}</span>}</article>})}</div>:<div className="orders-empty"><span>↗</span><b>No {filter==='all'?'practice orders':filter+' orders'} yet</b><p>{filter==='all'?'Place a virtual stock order and it will appear here.':'There are no orders in this category right now.'}</p></div>}</Card><p className="practice-disclaimer"><Info size={14}/> All prices and transactions on this page are simulated for learning. No broker connection or real funds are involved.</p></div>}
function FundPractice({data,update,trackActivity,notify,money}){const [selectedId,setSelectedId]=useState(practiceFundCatalog[0].id),[amount,setAmount]=useState('500'),[sipDay,setSipDay]=useState('5'),[search,setSearch]=useState('');const selected=practiceFundCatalog.find(fund=>fund.id===selectedId)||practiceFundCatalog[0],funds=practiceFundCatalog.filter(fund=>`${fund.name} ${fund.category}`.toLowerCase().includes(search.toLowerCase()));const invest=(fundId,value,kind='lumpsum')=>{const fund=practiceFundCatalog.find(item=>item.id===fundId),n=Number(value);if(!fund||n<=0){notify('Enter an amount above zero.');return false}if(n>Number(data.wallet||0)){notify('Not enough virtual wallet balance for this practice investment.');return false}update(state=>addFundUnits(state,fund,n,kind));trackActivity(`${kind==='sip'?'SIP installment':'Fund purchase'} · ${fund.name}`,`${money(n)} at illustrative NAV ${money(fund.nav)}`,-n);notify('Practice investment recorded.');return true};const createSip=()=>{const n=Number(amount);if(n<=0){notify('Enter a monthly amount above zero.');return}if(n>Number(data.wallet||0)){notify('Your virtual wallet does not cover this installment.');return}const plan={id:`sip-${Date.now()}`,fundId:selected.id,amount:n,day:Number(sipDay),installments:0,createdAt:Date.now()};update(state=>({...state,fundSips:[plan,...(state.fundSips||[])]}));trackActivity('Monthly practice SIP created',`${money(n)} · ${selected.name}`);notify('Monthly practice SIP created. Installments only run when you choose.');};const runSip=plan=>{if(invest(plan.fundId,plan.amount,'sip'))update(state=>({...state,fundSips:(state.fundSips||[]).map(item=>item.id===plan.id?{...item,installments:(item.installments||0)+1,lastRun:date()}:item)}))};const removeSip=id=>update(state=>({...state,fundSips:(state.fundSips||[]).filter(plan=>plan.id!==id)}));return <div className="fund-page"><div className="fund-intro"><span className="mtf-badge">MUTUAL FUND PRACTICE</span><h2>Explore funds and recurring investing</h2><p>Choose a practice fund, compare its risk category, and try a one-time purchase or a monthly SIP using virtual money.</p></div><div className="fund-layout"><Card title="Explore practice funds" extra={<span className="soft-tag">Illustrative NAVs</span>}><label className="market-search"><span>⌕</span><input aria-label="Search practice funds" value={search} onChange={event=>setSearch(event.target.value)} placeholder="Search funds"/></label><div className="fund-list">{funds.map(fund=><button key={fund.id} className={`fund-choice ${fund.id===selected.id?'active':''}`} onClick={()=>setSelectedId(fund.id)}><span className="fund-avatar">{fund.category==='Index'?'IDX':fund.category==='Hybrid'?'HYB':'D'}</span><span><b>{fund.name}</b><small>{fund.category} · Risk: {fund.risk}</small></span><span className="fund-nav"><small>NAV</small><b>{money(fund.nav)}</b></span></button>)}</div></Card><div className="fund-action-column"><Card title={selected.name} extra={<span className="soft-tag">{selected.category}</span>}><p className="muted">{selected.about}</p><div className="fund-details"><div><span>Illustrative NAV</span><b>{money(selected.nav)}</b></div><div><span>Risk category</span><b>{selected.risk}</b></div><div><span>Example fee</span><b>{selected.fee}</b></div></div><label className="field-label">Practice amount<input type="number" min="1" value={amount} onChange={event=>setAmount(event.target.value)}/><small>About {money((Number(amount)||0)/selected.nav)} units at this example NAV.</small></label><Button onClick={()=>invest(selected.id,amount)}>Practice one-time buy</Button><div className="sip-create"><h3>Set up a monthly practice SIP</h3><div className="sip-fields"><label className="field-label">Monthly amount<input type="number" min="1" value={amount} onChange={event=>setAmount(event.target.value)}/></label><label className="field-label">Day of month<select value={sipDay} onChange={event=>setSipDay(event.target.value)}>{[5,10,15,20,25].map(day=><option value={day} key={day}>{day}{day===5?'th':day===10?'th':day===15?'th':day===20?'th':'th'}</option>)}</select></label></div><Button kind="secondary" onClick={createSip}>Create monthly SIP</Button><p className="hint">No automatic payments. Run each installment yourself to keep it in practice mode.</p></div></Card></div></div><div className="fund-layout fund-lower"><Card title="Your practice fund holdings" extra={<span className="soft-tag">{(data.fundHoldings||[]).length} funds</span>}>{data.fundHoldings?.length?<div className="activity-list">{data.fundHoldings.map(holding=>{const fund=practiceFundCatalog.find(item=>item.id===holding.fundId);return <div className="activity-row" key={holding.fundId}><span className="fund-avatar">MF</span><span><b>{fund?.name||holding.fundId}</b><small>{holding.units.toFixed(3)} units · Invested {money(holding.invested)}</small></span><strong>{money(holding.units*(fund?.nav||0))}</strong></div>})}</div>:<div className="empty-state"><span>◉</span><b>No practice fund holdings</b><p>Your simulated fund purchases will appear here.</p></div>}</Card><Card title="Monthly practice SIPs" extra={<span className="soft-tag">{data.fundSips?.length||0} plans</span>}>{data.fundSips?.length?<div className="sip-list">{data.fundSips.map(plan=>{const fund=practiceFundCatalog.find(item=>item.id===plan.fundId);return <div className="sip-plan" key={plan.id}><span><b>{fund?.name||plan.fundId}</b><small>{money(plan.amount)} monthly · Day {plan.day} · {plan.installments||0} installments</small>{plan.lastRun&&<small>Last practice installment: {plan.lastRun}</small>}</span><div><Button kind="secondary" onClick={()=>runSip(plan)} disabled={Number(plan.amount)>Number(data.wallet||0)}>Run installment</Button><button className="sip-remove" onClick={()=>removeSip(plan.id)} aria-label="Remove SIP">×</button></div></div>})}</div>:<div className="empty-state"><span>↻</span><b>No SIP plans yet</b><p>Create a monthly practice plan to learn how recurring investments work.</p></div>}</Card></div><p className="practice-disclaimer"><Info size={14}/> These are made-up learning examples, not real mutual funds or investment recommendations. Values do not use live NAV data.</p></div>}
const practiceIpos=[{id:'northstar',name:'Northstar Learning',sector:'Education technology',bandLow:96,bandHigh:104,lot:140,closes:'Practice closes in 3 days',risk:'Early-stage growth company'},{id:'sunrise',name:'Sunrise Mobility',sector:'Electric transport',bandLow:218,bandHigh:232,lot:64,closes:'Practice closes in 5 days',risk:'Capital-intensive sector'},{id:'harbor',name:'Harbor Foods',sector:'Consumer staples',bandLow:82,bandHigh:90,lot:160,closes:'Practice opens soon',risk:'Competitive consumer market'}];
function IpoPractice({data,update,trackActivity,notify,money}){const [selectedId,setSelectedId]=useState(practiceIpos[0].id),[lots,setLots]=useState(1);const selected=practiceIpos.find(ipo=>ipo.id===selectedId)||practiceIpos[0],price=Math.round((selected.bandLow+selected.bandHigh)/2),amount=price*selected.lot*Math.max(1,Number(lots)||1),saveApplication=()=>{if((data.ipoApplications||[]).some(application=>application.ipoId===selected.id)){notify('You already saved a practice application for this offering.');return}const application={id:`ipo-${Date.now()}`,ipoId:selected.id,lots:Math.max(1,Number(lots)||1),price,amount,status:'practice-only',createdAt:Date.now()};update(state=>({...state,ipoApplications:[application,...(state.ipoApplications||[])]}));trackActivity('IPO practice application saved',`${selected.name} · ${money(amount)} application preview`);notify('Practice application saved. No mandate or funds were created.');};const removeApplication=id=>update(state=>({...state,ipoApplications:(state.ipoApplications||[]).filter(application=>application.id!==id)}));return <div className="ipo-page"><div className="fund-intro"><span className="mtf-badge">IPO PAPER PRACTICE</span><h2>Learn how an IPO application works</h2><p>Review a fictional offer, choose lots, and save an application preview. This does not submit an exchange order or create a payment mandate.</p></div><div className="ipo-layout"><Card title="Practice offerings" extra={<span className="soft-tag">Fictional companies</span>}><div className="ipo-list">{practiceIpos.map(ipo=><button className={`ipo-choice ${ipo.id===selected.id?'active':''}`} key={ipo.id} onClick={()=>setSelectedId(ipo.id)}><span className="ipo-symbol">{ipo.name.split(' ').map(word=>word[0]).join('').slice(0,2)}</span><span><b>{ipo.name}</b><small>{ipo.sector} · {ipo.closes}</small></span><span className="ipo-band"><small>Price band</small><b>{money(ipo.bandLow)}–{money(ipo.bandHigh)}</b></span></button>)}</div></Card><Card title={`Application preview · ${selected.name}`} extra={<span className="soft-tag">Practice only</span>}><div className="ipo-facts"><div><span>Price band</span><b>{money(selected.bandLow)} – {money(selected.bandHigh)}</b></div><div><span>Example lot size</span><b>{selected.lot} shares</b></div><div><span>Risk to consider</span><b>{selected.risk}</b></div></div><label className="field-label">Lots<input type="number" min="1" max="10" value={lots} onChange={event=>setLots(event.target.value)}/></label><div className="ipo-total"><span>Indicative application amount</span><b>{money(amount)}</b></div><Button onClick={saveApplication} disabled={(data.ipoApplications||[]).some(application=>application.ipoId===selected.id)}>Save practice application</Button><p className="hint">The amount is only a preview. No money leaves your virtual wallet and allotment is not simulated.</p></Card></div><Card title="Saved practice applications" extra={<span className="soft-tag">{data.ipoApplications?.length||0} saved</span>}>{data.ipoApplications?.length?<div className="activity-list">{data.ipoApplications.map(application=>{const ipo=practiceIpos.find(item=>item.id===application.ipoId);return <div className="activity-row" key={application.id}><span className="ipo-symbol">IPO</span><span><b>{ipo?.name||application.ipoId}</b><small>{application.lots} lots · {money(application.amount)} indicative · Practice only</small></span><button className="sip-remove" onClick={()=>removeApplication(application.id)}>×</button></div>})}</div>:<div className="empty-state"><span>◇</span><b>No saved applications</b><p>Choose a fictional offer to create a practice application preview.</p></div>}</Card><p className="practice-disclaimer"><Info size={14}/> Fictional examples for financial education only; not an offer or investment recommendation.</p></div>}
export default App;
